syntax:
namespace NamespaceName {
    // Member definitions go here
    return_type functionName(parameters) {
        // Implementation details
    }
    // Note: The compiler will mangle 'functionName' to include 'NamespaceName' (e.g., _ZN12NamespaceName11functionNameEvd for a function with parameters), ensuring unique linkage across translation units.

code_example:
#include <iostream>
namespace X {
    void f() {
        std::cout << "Hello from namespace X" << std::endl;
    }
}
